llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Estazolam, the closest analogue (Morgan 0.27), has 87% oral bioavailability in healthy volunteers, directly supporting high F for a chlorophenyl-fused heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Alprazolam, a chlorophenyl triazolobenzodiazepine, has absolute oral bioavailability of 80–100% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Adinazolam, which adds a basic amine to the alprazolam scaffold, has absolute F of 39% in healthy volunteers, still well above the 20% threshold and relevant to the query's basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Loxapine, a tricyclic chlorophenyl compound with a basic piperazine, has systemic availability of 29%, above the 20% threshold despite high hepatic extraction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Clobazam, a chlorophenyl benzodiazepine with N-methyl groups, has oral bioavailability of 87–100% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Triazolam, a chlorinated triazolobenzodiazepine, has oral bioavailability of 55±20% in healthy subjects, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Tenidap, a chlorophenyl heterocycle, had absolute bioavailability of 85% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Diltiazem, a lipophilic basic heterocycle, has absolute oral bioavailability of 38±11%, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "A single bupropion record reports 10% oral bioavailability, but this is an outlier contradicted by multiple bupropion records and comes from a less transferable scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence points to oral bioavailability above 20%: the closest analogues (estazolam, alprazolam, clobazam) show 80–100% F, and even analogues with first-pass liability (adinazolam, loxapine, triazolam, diltiazem) remain above 20%. The single low bupropion report is an outlier and less transferable. Therefore predict high F (≥20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "All analogues have Morgan similarity ≤0.27, limiting quantitative transfer.",
    "Physicochemical prior suggests poor solubility, but no experimental solubility or permeability data are available for the query.",
    "Conflicting bupropion bioavailability reports create minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

